// The command line and the vault reader, against folders on disk. The parity test runs
// every command over a made-up vault and compares stdout and the exit code with what
// hoard's own Python librarian printed for the same vault (tests/fixtures/librarian,
// regenerated by hoard-run.py there). The rest port hoard's command-line tests from
// test_dangling, test_quotes and test_relink, and the git-history test from test_manifest.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { after, test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { type Io, main } from '../../../src/librarian/cli.ts';
import { createHash } from 'node:crypto';
import { HOARD_LAYOUT } from '../../../src/librarian/scheme.ts';
import { readVault } from '../../../src/librarian/vault-fs.ts';

const FIXTURE = fileURLToPath(new URL('../../fixtures/librarian/', import.meta.url));
const SCHEME = path.join(FIXTURE, 'scheme.json');
const temps: string[] = [];
after(() => {
  for (const dir of temps) rmSync(dir, { recursive: true, force: true });
});

function tempDir(): string {
  const dir = realpathSync(mkdtempSync(path.join(tmpdir(), 'librarian-')));
  temps.push(dir);
  return dir;
}

function vault(files: Record<string, string | Buffer>): string {
  const root = tempDir();
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
    writeFileSync(path.join(root, rel), text);
  }
  return root;
}

interface Run {
  code: number;
  out: string;
  err: string;
}

function run(argv: string[], cwd = process.cwd(), env: Record<string, string | undefined> = {}): Run {
  let out = '';
  let err = '';
  const io: Io = { stdout: (s) => (out += s), stderr: (s) => (err += s), env, cwd };
  return { code: main(argv, io), out, err };
}

const PAGE = '---\ntype: subject\nprovenance:\n  generator: claude-opus-5\n---\n# X\n\n> [!librarian]- Agent-written page\n> r\n\n';

// --- parity with hoard ------------------------------------------------------------

interface Expected {
  argv: string[];
  code: number;
  stdout: string;
}

const EXPECTED: Expected[] = JSON.parse(readFileSync(path.join(FIXTURE, 'expected.json'), 'utf8'));

for (const { argv, code, stdout } of EXPECTED) {
  test(`parity with hoard: ${argv.join(' ')}`, () => {
    const root = path.join(tempDir(), 'vault');
    cpSync(path.join(FIXTURE, 'vault'), root, { recursive: true });
    const got = run([argv[0]!, '--vault', root, '--scheme', SCHEME, ...argv.slice(1)], root);
    assert.equal(got.out.replaceAll(root, '<vault>'), stdout);
    assert.equal(got.code, code);
  });
}

// --- dangling ---------------------------------------------------------------------

const HEAD = '---\ntype: subject\n---\n';

// A plain unresolved link is a writer's outline, so it never fails the check.
test('dangling exits 1 only on a near miss', () => {
  assert.equal(run(['dangling', '--vault', vault({ 'lore/A.md': `${HEAD}[[Nowhere]]\n` })]).code, 0);
  const typo = vault({ 'lore/Rivers-Ash-and-Stone.md': HEAD, 'lore/A.md': `${HEAD}[[Rivers-and-Stone]]\n` });
  assert.equal(run(['dangling', '--vault', typo]).code, 1);
});

// --match answers about one name, exit code included.
test('dangling --match filters the list and the exit code', () => {
  const root = vault({ 'lore/Rivers-Ash-and-Stone.md': HEAD, 'lore/A.md': `${HEAD}[[Rivers-and-Stone]] and [[Ossuary Ledger]]\n` });
  assert.equal(run(['dangling', '--vault', root]).code, 1);
  const got = run(['dangling', '--vault', root, '--match', 'OSSUARY-ledger']);
  assert.equal(got.code, 0);
  assert.ok(got.out.includes('[[Ossuary Ledger]]'));
  assert.ok(!got.out.includes('Rivers-and-Stone'));
  assert.ok(got.out.includes('1 unresolved target(s)'));
});

// --- quotes -------------------------------------------------------------------------

const SOURCE = '---\ntype: source\nprovenance:\n  origin: o\n  method: converted\n  author: the Long Read\n---\n'
  + 'It is a landscape of possibilities, a map of all the potential shapes.\n';

test('quotes exits 0 clean and 1 on a dead receipt', () => {
  const clean = vault({ 'sources/lanterns.md': SOURCE, 'lore/X.md': `${PAGE}A "map of all the potential shapes" ([[lanterns]] -- the Long Read, one).\n` });
  assert.equal(run(['quotes', '--vault', clean]).code, 0);
  const broken = vault({ 'sources/lanterns.md': SOURCE, 'lore/X.md': `${PAGE}A "map of all the potential biscuits" ([[lanterns]] -- the Long Read, one).\n` });
  assert.equal(run(['quotes', '--vault', broken]).code, 1);
});

// A capital adapted to the sentence is printed, and a vault with only that is green.
test('quotes: QV2 alone is printed and does not fail', () => {
  const cased = vault({ 'sources/lanterns.md': SOURCE, 'lore/X.md': `${PAGE}"A map of all the potential shapes" is how it goes ([[lanterns]] -- the Long Read, one).\n` });
  const got = run(['quotes', '--vault', cased]);
  assert.equal(got.code, 0);
  assert.ok(got.out.includes('QV2'));
});

// --- relink, report only ---------------------------------------------------------------

const MIRELO = '---\ntype: lore\nsetting: brs\naliases:\n- mirelo\n---\n';

test('relink --check reports and exits 1 without writing', () => {
  const root = vault({ "lore/Mirel'o.md": MIRELO, 'lore/X.md': `${HEAD}See [[mirelo]].\n` });
  const got = run(['relink', '--vault', root, '--check']);
  assert.equal(got.code, 1);
  assert.ok(got.out.includes("lore/X.md:4: [[mirelo]] -> [[Mirel'o|mirelo]]  [librarian]"));
  assert.ok(got.out.includes('1 rewrite(s) pending in 1 file(s): 1 librarian'));
  assert.equal(readFileSync(path.join(root, 'lore/X.md'), 'utf8'), `${HEAD}See [[mirelo]].\n`);
});

test('relink with nothing to rewrite says so and exits 0', () => {
  const got = run(['relink', '--vault', vault({ 'lore/X.md': `${HEAD}Plain.\n` }), '--check']);
  assert.equal(got.code, 0);
  assert.equal(got.out, 'librarian relink --check: nothing to rewrite\n');
});

test('relink refuses a live old name and --map-only with no map', () => {
  const live = vault({ 'lore/The Lantern.md': HEAD, 'lore/X.md': `${HEAD}[[The Lantern]]\n` });
  assert.equal(run(['relink', '--vault', live, '--check', '--map', 'The Lantern=The-Lantern']).code, 3);
  assert.equal(run(['relink', '--vault', live, '--check', '--map-only']).code, 3);
});

test('relink reads a map file', () => {
  const root = vault({ 'lore/The-Lantern.md': HEAD, 'lore/X.md': `${HEAD}[[The Lantern]]\n`, 'map.txt': '# renames\nThe Lantern -> The-Lantern\n' });
  const got = run(['relink', '--vault', root, '--check', '--map-file', 'map.txt'], root);
  assert.equal(got.code, 1);
  assert.ok(got.out.includes('lore/X.md:4: [[The Lantern]] -> [[The-Lantern]]  [librarian]'));
});

// Relink-Reports-Only: hoard applies rewrites; the port never writes a note.
test('relink --apply is refused as a usage error, and nothing is written', () => {
  const root = vault({ "lore/Mirel'o.md": MIRELO, 'lore/X.md': `${HEAD}See [[mirelo]].\n` });
  const got = run(['relink', '--vault', root, '--apply']);
  assert.equal(got.code, 2);
  assert.ok(got.err.includes('--apply'));
  assert.equal(readFileSync(path.join(root, 'lore/X.md'), 'utf8'), `${HEAD}See [[mirelo]].\n`);
});

// --- the manifest commands ----------------------------------------------------------------

const sha = (data: string | Buffer) => createHash('sha256').update(data).digest('hex');
const manifest = (records: object[]) => records.map((r) => `${JSON.stringify(r)}\n`).join('');

test('repair reports a fixable absolute dest and exits 1, writing nothing', () => {
  const root = tempDir();
  const text = manifest([{ src: 's', dest: `${root}/lore/a.md`, method: 'converted', src_sha256: 'x' }]);
  mkdirSync(path.join(root, '_meta'));
  writeFileSync(path.join(root, '_meta/MANIFEST.jsonl'), text);
  const got = run(['repair', '--vault', root]);
  assert.equal(got.code, 1);
  assert.equal(got.out, `dest absolute -> vault-relative: ${root}/lore/a.md -> lore/a.md\n`);
  assert.equal(readFileSync(path.join(root, '_meta/MANIFEST.jsonl'), 'utf8'), text);
  assert.equal(run(['repair', '--vault', root, '--apply']).code, 2);
});

test('repair and verify are clean on a vault with no manifest', () => {
  const root = vault({ 'lore/x.md': HEAD });
  assert.deepEqual([run(['repair', '--vault', root]).code, run(['repair', '--vault', root]).out], [0, '']);
  assert.equal(run(['verify', '--vault', root]).code, 0);
});

test('check needs a hashable source', () => {
  const root = vault({});
  const got = run(['check', '--vault', root, '--src', 'nowhere/at-all.md'], root);
  assert.equal(got.code, 3);
  assert.ok(got.err.includes('check: no hashable source (pass --src-file)'));
});

test('check finds an ingested source by its own path', () => {
  const root = vault({ 'in/a.txt': 'hello\n' });
  mkdirSync(path.join(root, '_meta'));
  writeFileSync(path.join(root, '_meta/MANIFEST.jsonl'), manifest([{ src: 'in/a.txt', dest: 'sources/a.md', method: 'converted', src_sha256: sha('hello\n') }]));
  const got = run(['check', '--vault', root, '--src', 'in/a.txt'], root);
  assert.deepEqual([got.code, got.out], [0, 'ingested (1 record(s))\n']);
});

// A verbatim page the author has edited since is evolution, not breakage, when the
// pinned hash is in the page's history, renames followed.
test('verify accepts authorial evolution from git history, across a rename', () => {
  const root = vault({ 'writing/old.md': '---\ntype: writing\n---\nAs it came in.\n' });
  const git = (...args: string[]) => execFileSync('git', ['-C', root, '-c', 'user.name=t', '-c', 'user.email=t@example.com', ...args],
    { stdio: 'pipe' });
  git('init', '-q');
  git('add', '.');
  git('commit', '-qm', 'ingest');
  git('mv', 'writing/old.md', 'writing/new.md');
  git('commit', '-qm', 'rename');
  writeFileSync(path.join(root, 'writing/new.md'), '---\ntype: writing\n---\nAs the author left it.\n');
  git('commit', '-qam', 'revise');
  mkdirSync(path.join(root, '_meta'));
  const pinned = { src: 'o', dest: 'writing/new.md', method: 'verbatim', src_sha256: 'x', body_sha256: sha('As it came in.\n') };
  writeFileSync(path.join(root, '_meta/MANIFEST.jsonl'), manifest([pinned]));
  const got = run(['verify', '--vault', root]);
  assert.deepEqual([got.code, got.out], [0, '']);
  assert.ok(got.err.includes('evolved since ingest'));
  writeFileSync(path.join(root, '_meta/MANIFEST.jsonl'), manifest([{ ...pinned, body_sha256: sha('Never there.\n') }]));
  assert.deepEqual(run(['verify', '--vault', root]).out, 'writing/new.md: hash mismatch — verbatim law broken (src o)\n');
});

test('verify hashes a non-Markdown dest as bytes', () => {
  const bytes = Buffer.from([0x00, 0xff, 0x10, 0x80]);
  const root = vault({ 'sources/a.bin': bytes });
  mkdirSync(path.join(root, '_meta'));
  writeFileSync(path.join(root, '_meta/MANIFEST.jsonl'), manifest([{ src: 'o', dest: 'sources/a.bin', method: 'verbatim', src_sha256: 'x', file_sha256: sha(bytes) }]));
  assert.equal(run(['verify', '--vault', root]).code, 0);
});

// --- the reader, logs and errors ------------------------------------------------------------

// Python's read_text() reads through universal newlines and keeps a byte-order mark.
test('the reader turns CRLF and CR into LF and keeps a BOM', () => {
  const root = vault({ 'lore/a.md': '---\r\ntype: lore\r\n---\rbody\r\n', 'lore/b.md': '\ufeffbody\n' });
  const { notes } = readVault(root, HOARD_LAYOUT);
  assert.deepEqual(notes, [['lore/a.md', '---\ntype: lore\n---\nbody\n'], ['lore/b.md', '\ufeffbody\n']]);
});

test('the reader walks in path order and leaves out tooling and fixtures', () => {
  const root = vault({
    'a-b/x.md': '1', 'a/x.md': '2', 'lore.md': '3', 'lore/x.md': '4', '.git/README.md': '5', 'lore/.obsidian/x.md': '6',
    '_meta/infra/derived/x.md': '7', '_meta/infra/tools/tests/fixtures/f/lore/X.md': '8', 'sources/map.canvas': '{}',
    'sources/.gitkeep': '', '_meta/x.png': '',
  });
  const { notes, attachments } = readVault(root, HOARD_LAYOUT);
  assert.deepEqual(notes.map(([rel]) => rel), ['a/x.md', 'a-b/x.md', 'lore/x.md', 'lore.md']);
  assert.deepEqual(attachments, ['sources/map.canvas']);
});

test('a note that is not UTF-8 is an error, exit 3', () => {
  const got = run(['lint', '--vault', vault({ 'lore/x.md': Buffer.from([0x66, 0xff, 0x0a]) })]);
  assert.equal(got.code, 3);
  assert.ok(got.err.includes('librarian lint failed'));
});

test('logs are JSON lines on stderr, info and up', () => {
  const got = run(['lint', '--vault', vault({ 'lore/x.md': 'no fm\n' })]);
  const records = got.err.trim().split('\n').map((line) => JSON.parse(line));
  assert.deepEqual(records.map((r) => r.message), ['lint: indexed 1 notes for link resolution', 'lint: 1 note findings']);
  assert.ok(records.every((r) => r.logger === 'librarian.lint' && r.level === 'info'));
});

test('HOARD_TIMING=1 times the command on stderr', () => {
  const root = vault({ 'lore/x.md': 'no fm\n' });
  assert.match(run(['lint', '--vault', root], undefined, { HOARD_TIMING: '1' }).err, /^lint: \d+ms$/m);
  assert.doesNotMatch(run(['lint', '--vault', root]).err, /^lint: \d+ms$/m);
});

test('the vault defaults to the working folder', () => {
  const root = vault({ 'lore/x.md': 'no fm\n' });
  assert.deepEqual(run(['lint'], root).out, 'lore/x.md: FM1 missing frontmatter\n');
});

test('a scheme file sets the speakers and roles', () => {
  const root = vault({ 'lore/x.md': '---\ntype: meta\nrole: [gardener]\n---\n' });
  assert.equal(run(['lint', '--vault', root]).code, 1);
  assert.equal(run(['lint', '--vault', root, '--scheme', SCHEME]).code, 1);
  assert.ok(!run(['lint', '--vault', root, '--scheme', SCHEME]).out.includes('FM7'));
});

test('a scheme file that is not a scheme is an error', () => {
  const root = vault({ 'bad.json': '{"roles": "writer"}' });
  const got = run(['lint', '--vault', root, '--scheme', path.join(root, 'bad.json')]);
  assert.equal(got.code, 3);
  assert.ok(got.err.includes('roles'));
});

test('usage errors exit 2', () => {
  assert.equal(run([]).code, 2);
  assert.equal(run(['frobnicate']).code, 2);
  assert.equal(run(['check']).code, 2);
  assert.equal(run(['lint', '--bogus']).code, 2);
  assert.equal(run(['relink', '--scope', 'everything']).code, 2);
  assert.equal(run(['lint', '--layout', 'neo']).code, 2);
});
